function isReadOnlyTransactionError(error) {
  const code = String(error?.code || '').trim();
  if (code === '25006') return true;

  const message = String(error?.message || '').toLowerCase();
  return message.includes('read-only transaction') || message.includes('cannot execute') && message.includes('read-only');
}

function buildTelemetryResult({
  stored = false,
  skipped = false,
  reason = null,
  error = null,
} = {}) {
  return {
    stored,
    skipped,
    reason,
    error,
  };
}

function normalizeEntityType(raw) {
  const value = String(raw || '')
    .trim()
    .toLowerCase();
  if (!value) return null;
  if (value === 'profile') return ENTITY_TYPES.user;
  if (value === 'events') return ENTITY_TYPES.event;
  if (value === 'exhibitions') return ENTITY_TYPES.exhibition;
  if (value === 'governance') return ENTITY_TYPES.dao;
  if (value === 'community_post' || value === 'communitypost') return ENTITY_TYPES.post;
  if (value in ENTITY_TYPES) return value;
  return null;
}

function normalizeEntityIdForType(entityType, entityId) {
  if (entityType === ENTITY_TYPES.user) return canonicalWallet(entityId);
  if (entityType === ENTITY_TYPES.platform) return 'global';
  if (entityType === ENTITY_TYPES.dao) {
    const value = String(entityId || '')
      .trim()
      .toLowerCase();
    if (!value) return '';
    if (value === 'dao' || value === 'governance' || value === 'global' || value === 'art-kubus' || value === 'art.kubus') {
      return 'governance';
    }
    const error = new Error('Invalid entityId');
    error.statusCode = 400;
    throw error;
  }
  return String(entityId || '').trim();
}

function normalizeScope(raw) {
  const value = String(raw || '')
    .trim()
    .toLowerCase();
  if (!value) return 'public';
  if (value === 'public' || value === 'private') return value;
  const error = new Error('Invalid scope');
  error.statusCode = 400;
  throw error;
}

function parseCsvList(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) {
    return raw.flatMap((value) => parseCsvList(value));
  }
  return String(raw)
    .split(',')
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function normalizeBucket(rawBucket, timeframe) {
  const value = String(rawBucket || '')
    .trim()
    .toLowerCase();
  if (value in BUCKETS) return value;
  if (
    String(timeframe || '')
      .trim()
      .toLowerCase() === '24h'
  )
    return BUCKETS.hour;
  return BUCKETS.day;
}

function parseTimeframeWindow({ timeframe, from, to, bucket }) {
  const now = new Date();
  const normalizeDate = (value) => {
    if (!value) return null;
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  };

  const explicitFrom = normalizeDate(from);
  const explicitTo = normalizeDate(to);
  const resolvedTo = explicitTo || now;

  if (explicitFrom) {
    return {
      from: explicitFrom,
      to: resolvedTo,
      bucket: normalizeBucket(bucket, timeframe)
    };
  }

  const tf = String(timeframe || '')
    .trim()
    .toLowerCase();
  const ms = (() => {
    switch (tf) {
      case '24h':
        return 24 * 60 * 60 * 1000;
      case '7d':
        return 7 * 24 * 60 * 60 * 1000;
      case '30d':
        return 30 * 24 * 60 * 60 * 1000;
      case '90d':
        return 90 * 24 * 60 * 60 * 1000;
      case '1y':
        return 365 * 24 * 60 * 60 * 1000;
      default:
        return 30 * 24 * 60 * 60 * 1000;
    }
  })();

  return {
    from: new Date(resolvedTo.getTime() - ms),
    to: resolvedTo,
    bucket: normalizeBucket(bucket, tf)
  };
}

function allowedPublicMetricsForEntity(entityType) {
  if (entityType === ENTITY_TYPES.user) return USER_PUBLIC_METRICS;
  if (entityType === ENTITY_TYPES.platform) return PLATFORM_PUBLIC_METRICS;
  if (entityType === ENTITY_TYPES.dao) return DAO_PUBLIC_METRICS;
  if (entityType === ENTITY_TYPES.collection) return COLLECTION_PUBLIC_METRICS;
  if (entityType === ENTITY_TYPES.event) return EVENT_PUBLIC_METRICS;
  if (entityType === ENTITY_TYPES.exhibition) return EXHIBITION_PUBLIC_METRICS;
  return CONTENT_PUBLIC_METRICS;
}

function allowedMetricSetForEntity(entityType, scope) {
  if (entityType === ENTITY_TYPES.dao && scope === 'private') {
    return new Set();
  }
  const allowed = new Set(allowedPublicMetricsForEntity(entityType));
  if (scope === 'private' && entityType === ENTITY_TYPES.user) {
    for (const metric of USER_PRIVATE_METRICS) {
      allowed.add(metric);
    }
  }
  return allowed;
}

function allowedSeriesMetricSetForEntity(entityType, scope) {
  const snapshotAllowed = allowedMetricSetForEntity(entityType, scope);
  const seriesAllowed = (() => {
    if (entityType === ENTITY_TYPES.user) {
      return scope === 'private' ? USER_PRIVATE_SERIES_METRICS : USER_PUBLIC_SERIES_METRICS;
    }
    if (entityType === ENTITY_TYPES.platform) return PLATFORM_SERIES_METRICS;
    if (entityType === ENTITY_TYPES.dao) return DAO_SERIES_METRICS;
    if (entityType === ENTITY_TYPES.event) return EVENT_SERIES_METRICS;
    if (entityType === ENTITY_TYPES.exhibition) return EXHIBITION_SERIES_METRICS;
    if (entityType === ENTITY_TYPES.collection) return [];
    return CONTENT_SERIES_METRICS;
  })();

  return new Set(seriesAllowed.filter((metric) => snapshotAllowed.has(metric)));
}

function normalizeMetricList(entityType, rawMetrics, scope) {
  const requested = parseCsvList(rawMetrics);
  const hasRequested = requested.length > 0;
  const allowed = allowedMetricSetForEntity(entityType, scope);

  const metrics = hasRequested ? requested : [...allowed];
  const unsupported = metrics.filter((metric) => !allowed.has(metric));
  if (unsupported.length > 0) {
    const error = new Error(`Unsupported metric: ${unsupported[0]}`);
    error.statusCode = 400;
    throw error;
  }

  const seen = new Set();
  return metrics.filter((metric) => {
    if (seen.has(metric)) return false;
    seen.add(metric);
    return true;
  });
}

function normalizeSnapshotGroupBy(groupBy) {
  const value = String(groupBy || '').trim();
  if (!value) return null;
  const error = new Error('Unsupported groupBy');
  error.statusCode = 400;
  throw error;
}

function normalizeGroupByForSeries({ entityType, metric, groupBy }) {
  const value = String(groupBy || '').trim();
  if (!value) return null;

  const allowed = (() => {
    if (entityType === ENTITY_TYPES.user && metric === 'viewsReceived') {
      return new Set(['source', 'targetType']);
    }
    if (entityType === ENTITY_TYPES.platform && metric === 'views') {
      return new Set(['source', 'targetType']);
    }
    if (
      entityType === ENTITY_TYPES.dao &&
      [
        'daoTotalProposals',
        'daoActiveProposals',
        'daoVotesCast',
        'daoTreasuryInflow',
        'daoTreasuryOutflow',
        'daoRecentTransactions'
      ].includes(metric)
    ) {
      return new Set(['targetType']);
    }
    if (
      (entityType === ENTITY_TYPES.artwork || entityType === ENTITY_TYPES.post) &&
      (metric === 'views' || metric === 'shares')
    ) {
      return new Set(['source']);
    }
    if (
      (entityType === ENTITY_TYPES.event || entityType === ENTITY_TYPES.exhibition) &&
      (metric === 'views' || metric === 'shares')
    ) {
      return new Set(['source']);
    }
    return new Set();
  })();

  if (!allowed.has(value)) {
    const error = new Error('Unsupported groupBy');
    error.statusCode = 400;
    throw error;
  }
  return value;
}

function getMetadata() {
  const entityTypes = Object.values(ENTITY_TYPES);
  const metricScopes = {};
  for (const entityType of entityTypes) {
    const publicMetrics = [...allowedMetricSetForEntity(entityType, 'public')];
    const privateMetrics = [...allowedMetricSetForEntity(entityType, 'private')];
    metricScopes[entityType] = {
      public: publicMetrics,
      private: privateMetrics
    };
  }

  return {
    entityTypes,
    scopes: ['public', 'private'],
    buckets: Object.values(BUCKETS),
    metrics: metricScopes,
    seriesMetrics: Object.fromEntries(
      entityTypes.map((entityType) => [
        entityType,
        {
          public: [...allowedSeriesMetricSetForEntity(entityType, 'public')],
          private: [...allowedSeriesMetricSetForEntity(entityType, 'private')]
        }
      ])
    ),
    seriesGroupBy: {
      user: {
        viewsReceived: ['source', 'targetType']
      },
      artwork: {
        views: ['source'],
        shares: ['source']
      },
      post: {
        views: ['source'],
        shares: ['source']
      },
      event: {
        views: ['source'],
        shares: ['source']
      },
      exhibition: {
        views: ['source'],
        shares: ['source']
      },
      dao: {
        daoTotalProposals: ['targetType'],
        daoActiveProposals: ['targetType'],
        daoVotesCast: ['targetType'],
        daoTreasuryInflow: ['targetType'],
        daoTreasuryOutflow: ['targetType'],
        daoRecentTransactions: ['targetType']
      },
      platform: {
        views: ['source', 'targetType']
      }
    }
  };
}

async function resolveUserContext(walletAddress) {
  const requested = canonicalWallet(walletAddress);
  if (!requested) return { walletAddress: '', userId: null, profileId: null };

  const profileResult = await query(
    `SELECT p.id AS profile_id, p.wallet_address, p.user_id
     FROM profiles p
     WHERE ${walletMatchClause('p.wallet_address', 1)}
     ORDER BY (p.wallet_address = $1) DESC, p.updated_at DESC
     LIMIT 1`,
    [requested]
  );

  if (profileResult.rows.length === 0) {
    const userResult = await query(
      `SELECT id, wallet_address FROM users WHERE ${walletMatchClause('wallet_address', 1)} ORDER BY (wallet_address = $1) DESC LIMIT 1`,
      [requested]
    );
    const row = userResult.rows[0];
    return {
      walletAddress: canonicalWallet(row?.wallet_address || requested),
      userId: row?.id || null,
      profileId: null
    };
  }

  const profileRow = profileResult.rows[0];
  const normalizedWallet = canonicalWallet(profileRow.wallet_address || requested);
  let userId = profileRow.user_id || null;

  if (!userId) {
    const userResult = await query(
      `SELECT id FROM users WHERE ${walletMatchClause('wallet_address', 1)} ORDER BY (wallet_address = $1) DESC LIMIT 1`,
      [normalizedWallet]
    );
    userId = userResult.rows[0]?.id || null;
  }

  return {
    walletAddress: normalizedWallet,
    userId,
    profileId: profileRow.profile_id || null
  };
}

async function resolveRequesterUserId(req) {
  if (!req?.user) return null;
  if (req.user.id) return req.user.id;
  const wallet = req.user.walletAddress || req.user.wallet || req.user.wallet_address;
  if (!wallet) return null;
  const result = await query(
    `SELECT id FROM users WHERE ${walletMatchClause('wallet_address', 1)} ORDER BY (wallet_address = $1) DESC LIMIT 1`,
    [wallet]
  );
  return result.rows[0]?.id || null;
}

function resolveRequesterWallet(req) {
  if (!req?.user) return '';
  return canonicalWallet(req.user.walletAddress || req.user.wallet || req.user.wallet_address);
}

async function canAccessPrivateStats({ entityType, entityId, req }) {
  if (!req?.user) return false;

  const requesterWallet = resolveRequesterWallet(req);
  const requesterUserId = await resolveRequesterUserId(req);

  if (entityType === ENTITY_TYPES.platform) {
    const role = (req.user.role || '').toString().trim().toLowerCase();
    return role === 'admin';
  }

  if (entityType === ENTITY_TYPES.user) {
    return requesterWallet && walletsEqual(requesterWallet, entityId);
  }

  if (!requesterUserId && !requesterWallet) return false;

  if (entityType === ENTITY_TYPES.artwork) {
    if (!UUID_REGEX.test(entityId)) return false;
    const result = await query(`SELECT wallet_address, creator_id FROM artworks WHERE id = $1 LIMIT 1`, [entityId]);
    const row = result.rows[0];
    if (!row) return false;
    if (requesterUserId && row.creator_id && row.creator_id === requesterUserId) return true;
    return requesterWallet && walletsEqual(requesterWallet, row.wallet_address);
  }

  if (entityType === ENTITY_TYPES.collection) {
    if (!UUID_REGEX.test(entityId)) return false;
    const result = await query(`SELECT wallet_address, owner_id FROM collections WHERE id = $1 LIMIT 1`, [entityId]);
    const row = result.rows[0];
    if (!row) return false;
    if (requesterUserId && row.owner_id && row.owner_id === requesterUserId) return true;
    return requesterWallet && walletsEqual(requesterWallet, row.wallet_address);
  }

  if (entityType === ENTITY_TYPES.post) {
    if (!UUID_REGEX.test(entityId)) return false;
    const result = await query(`SELECT wallet_address, author_id FROM community_posts WHERE id = $1 LIMIT 1`, [
      entityId
    ]);
    const row = result.rows[0];
    if (!row) return false;
    if (requesterUserId && row.author_id && row.author_id === requesterUserId) return true;
    return requesterWallet && walletsEqual(requesterWallet, row.wallet_address);
  }

  if (entityType === ENTITY_TYPES.event || entityType === ENTITY_TYPES.exhibition) {
    if (!UUID_REGEX.test(entityId)) return false;
    if (!requesterUserId) return false;
    const collabEntityType = entityType === ENTITY_TYPES.event ? 'events' : 'exhibitions';
    const result = await query(
      `SELECT role
       FROM collaboration_members
       WHERE entity_type = $1
         AND entity_id = $2
         AND member_user_id = $3
       ORDER BY created_at ASC
       LIMIT 1`,
      [collabEntityType, entityId, requesterUserId]
    );
    const role = (result.rows[0]?.role || '').toString().trim().toLowerCase();
    return role === 'owner' || role === 'admin' || role === 'publisher';
  }

  return false;
}

async function fetchUserSnapshot({ walletAddress, userId, metrics, scope }) {
  const isPublicScope = scope !== 'private';
  const wantsEngagement = metrics.includes('engagement');
  const wantsLikesReceived = metrics.includes('likesReceived') || wantsEngagement;
  const wantsViewsReceived = metrics.includes('viewsReceived') || wantsEngagement;
  const wantsCommentsReceived = wantsEngagement;
  const wantsSharesReceived = wantsEngagement;
  const wantsSavesReceived = wantsEngagement;

  const promises = {
    posts: metrics.includes('posts')
      ? query(
          `SELECT COUNT(*)::int AS count
         FROM community_posts
         WHERE ${walletMatchClause('wallet_address', 1)}
           AND is_active = true
           AND ($2::boolean = false OR is_public = true)`,
          [walletAddress, isPublicScope]
        )
      : null,
    artworks: metrics.includes('artworks')
      ? query(
          `SELECT COUNT(*)::int AS count
         FROM artworks
         WHERE ${walletMatchClause('wallet_address', 1)}
           AND is_active = true
           AND ($2::boolean = false OR is_public = true)`,
          [walletAddress, isPublicScope]
        )
      : null,
    publicStreetArtAdded: metrics.includes('publicStreetArtAdded')
      ? query(
          `SELECT COUNT(*)::int AS count
         FROM art_markers am
         WHERE am.is_active = true
           AND (
             lower(COALESCE(am.marker_data->>'markerType', am.marker_data->>'type', '')) IN ('streetart', 'street_art', 'street-art', 'publicart', 'public_art', 'public-art')
             OR lower(COALESCE(am.marker_data->>'markerType', am.marker_data->>'type', '')) LIKE '%street art%'
             OR lower(COALESCE(am.marker_data->>'markerType', am.marker_data->>'type', '')) LIKE '%public art%'
           )
           AND (
             ($1::text IS NOT NULL AND lower(COALESCE(am.marker_data->>'createdBy', am.marker_data->>'created_by', '')) = lower($1))
             OR ($2::uuid IS NOT NULL AND COALESCE(am.marker_data->>'createdBy', am.marker_data->>'created_by', '') = $2::text)
           )
           AND ($3::boolean = false OR lower(COALESCE(am.marker_data->>'isPublic', am.marker_data->>'is_public', 'true')) = 'true')`,
          [walletAddress, userId, isPublicScope]
        )
      : null,
    arEnabledArtworks: metrics.includes('arEnabledArtworks')
      ? query(
          `SELECT COUNT(*)::int AS count
         FROM artworks
         WHERE ${walletMatchClause('wallet_address', 1)}
           AND is_ar_enabled = true
           AND is_active = true
           AND ($2::boolean = false OR is_public = true)`,
          [walletAddress, isPublicScope]
        )
      : null,
    collections: metrics.includes('collections')
      ? query(
          `SELECT COUNT(*)::int AS count
         FROM collections
         WHERE ${walletMatchClause('wallet_address', 1)}`,
          [walletAddress]
        )
      : null,
    nftsMinted: metrics.includes('nftsMinted')
      ? query(
          `SELECT COUNT(*)::int AS count
         FROM artworks
         WHERE ${walletMatchClause('wallet_address', 1)}
           AND is_nft = true
           AND is_active = true
           AND nft_mint_address IS NOT NULL
           AND trim(nft_mint_address) <> ''
           AND ($2::boolean = false OR is_public = true)`,
          [walletAddress, isPublicScope]
        )
      : null,
    followers: metrics.includes('followers')
      ? userId
        ? query('SELECT COUNT(*)::int AS count FROM follows WHERE following_id = $1', [userId])
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    following: metrics.includes('following')
      ? userId
        ? query('SELECT COUNT(*)::int AS count FROM follows WHERE follower_id = $1', [userId])
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    comments: metrics.includes('comments')
      ? userId
        ? query('SELECT COUNT(*)::int AS count FROM comments WHERE author_id = $1', [userId])
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    likesGiven: metrics.includes('likesGiven')
      ? userId
        ? query('SELECT COUNT(*)::int AS count FROM likes WHERE user_id = $1', [userId])
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    viewsGiven: metrics.includes('viewsGiven')
      ? userId
        ? query('SELECT COUNT(*)::int AS count FROM views WHERE user_id = $1', [userId])
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    likesReceived: wantsLikesReceived
      ? Promise.all([
          query(
            `SELECT COALESCE(SUM(likes_count), 0)::int AS total
           FROM artworks
           WHERE ${walletMatchClause('wallet_address', 1)}
             AND is_active = true
             AND ($2::boolean = false OR is_public = true)`,
            [walletAddress, isPublicScope]
          ),
          query(
            `SELECT COALESCE(SUM(likes_count), 0)::int AS total
           FROM community_posts
           WHERE ${walletMatchClause('wallet_address', 1)}
             AND is_active = true
             AND ($2::boolean = false OR is_public = true)`,
            [walletAddress, isPublicScope]
          )
        ])
      : null,
    viewsReceived: wantsViewsReceived
      ? Promise.all([
          query(
            `SELECT COALESCE(SUM(views_count), 0)::int AS total
           FROM artworks
           WHERE ${walletMatchClause('wallet_address', 1)}
             AND is_active = true
             AND ($2::boolean = false OR is_public = true)`,
            [walletAddress, isPublicScope]
          ),
          query(
            `SELECT COALESCE(SUM(views_count), 0)::int AS total
           FROM community_posts
           WHERE ${walletMatchClause('wallet_address', 1)}
             AND is_active = true
             AND ($2::boolean = false OR is_public = true)`,
            [walletAddress, isPublicScope]
          )
        ])
      : null,
    commentsReceived: wantsCommentsReceived
      ? Promise.all([
          query(
            `SELECT COALESCE(SUM(comments_count), 0)::int AS total
           FROM artworks
           WHERE ${walletMatchClause('wallet_address', 1)}
             AND is_active = true
             AND ($2::boolean = false OR is_public = true)`,
            [walletAddress, isPublicScope]
          ),
          query(
            `SELECT COALESCE(SUM(comments_count), 0)::int AS total
           FROM community_posts
           WHERE ${walletMatchClause('wallet_address', 1)}
             AND is_active = true
             AND ($2::boolean = false OR is_public = true)`,
            [walletAddress, isPublicScope]
          )
        ])
      : null,
    sharesReceived: wantsSharesReceived
      ? Promise.all([
          query(
            `SELECT COALESCE(SUM(shares_count), 0)::int AS total
           FROM artworks
           WHERE ${walletMatchClause('wallet_address', 1)}
             AND is_active = true
             AND ($2::boolean = false OR is_public = true)`,
            [walletAddress, isPublicScope]
          ),
          query(
            `SELECT COALESCE(SUM(shares_count), 0)::int AS total
           FROM community_posts
           WHERE ${walletMatchClause('wallet_address', 1)}
             AND is_active = true
             AND ($2::boolean = false OR is_public = true)`,
            [walletAddress, isPublicScope]
          )
        ])
      : null,
    savesReceived: wantsSavesReceived
      ? query(
          `SELECT COUNT(*)::int AS count
         FROM bookmarks b
         LEFT JOIN artworks aw ON b.target_type = 'artwork' AND b.target_id = aw.id
         LEFT JOIN community_posts cp ON b.target_type = 'post' AND b.target_id = cp.id
         WHERE (
           (${walletMatchClause('aw.wallet_address', 1)} AND aw.is_active = true AND ($2::boolean = false OR aw.is_public = true))
           OR
           (${walletMatchClause('cp.wallet_address', 1)} AND cp.is_active = true AND ($2::boolean = false OR cp.is_public = true))
         )`,
          [walletAddress, isPublicScope]
        )
      : null,
    artworksDiscovered: metrics.includes('artworksDiscovered')
      ? userId
        ? query('SELECT COUNT(*)::int AS count FROM artwork_discoveries WHERE user_id = $1', [userId])
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    arSessions: metrics.includes('arSessions')
      ? userId
        ? query(
            `SELECT COUNT(*)::int AS count
           FROM analytics_events
           WHERE event_type = 'ar_session_start'
             AND (user_id = $1 OR actor_user_id = $1::text)`,
            [userId]
          )
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    eventsHosted: metrics.includes('eventsHosted')
      ? userId
        ? query(
            `SELECT COUNT(*)::int AS count
           FROM events e
           JOIN collaboration_members cm
             ON cm.entity_type = 'events'
            AND cm.entity_id = e.id
            AND cm.member_user_id = $1
            AND cm.role = 'owner'
           WHERE ($2::boolean = false OR e.status = 'published')`,
            [userId, isPublicScope]
          )
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    exhibitions: metrics.includes('exhibitions')
      ? userId
        ? query(
            `SELECT COUNT(DISTINCT ex.id)::int AS count
           FROM exhibitions ex
           JOIN collaboration_members cm
             ON cm.entity_type = 'exhibitions'
            AND cm.entity_id = ex.id
            AND cm.member_user_id = $1
           WHERE ($2::boolean = false OR ex.status = 'published')`,
            [userId, isPublicScope]
          )
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    exhibitionArtworks: metrics.includes('exhibitionArtworks')
      ? userId
        ? query(
            `SELECT COUNT(DISTINCT ea.artwork_id)::int AS count
           FROM exhibitions ex
           JOIN collaboration_members cm
             ON cm.entity_type = 'exhibitions'
            AND cm.entity_id = ex.id
            AND cm.member_user_id = $1
            AND cm.role = 'owner'
           LEFT JOIN exhibition_artworks ea ON ea.exhibition_id = ex.id
           WHERE ($2::boolean = false OR ex.status = 'published')`,
            [userId, isPublicScope]
          )
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    visitorsReceived: metrics.includes('visitorsReceived')
      ? userId
        ? query(
            `SELECT COUNT(*)::int AS count
           FROM analytics_events ae
           LEFT JOIN events e
             ON ae.target_type = 'event'
            AND ae.target_id = e.id
           LEFT JOIN exhibitions ex
             ON ae.target_type = 'exhibition'
            AND ae.target_id = ex.id
           WHERE ae.event_type = 'view'
             AND (
               (
                 ae.target_type = 'event'
                 AND e.id IS NOT NULL
                 AND ($2::boolean = false OR e.status = 'published')
                 AND EXISTS (
                   SELECT 1 FROM collaboration_members cm
                   WHERE cm.entity_type = 'events'
                     AND cm.entity_id = e.id
                     AND cm.member_user_id = $1
                     AND cm.role = 'owner'
                 )
               )
               OR
               (
                 ae.target_type = 'exhibition'
                 AND ex.id IS NOT NULL
                 AND ($2::boolean = false OR ex.status = 'published')
                 AND EXISTS (
                   SELECT 1 FROM collaboration_members cm
                   WHERE cm.entity_type = 'exhibitions'
                     AND cm.entity_id = ex.id
                     AND cm.member_user_id = $1
                     AND cm.role = 'owner'
                 )
               )
             )`,
            [userId, isPublicScope]
          )
        : Promise.resolve({ rows: [{ count: 0 }] })
      : null,
    achievementsUnlocked: metrics.includes('achievementsUnlocked')
      ? query(
          'SELECT COUNT(*)::int AS count FROM user_achievements WHERE wallet_address = $1 OR lower(wallet_address) = lower($1)',
          [walletAddress]
        )
      : null,
    achievementTokensTotal: metrics.includes('achievementTokensTotal')
      ? query(
          `SELECT COALESCE(SUM(a.reward_kub8), 0)::int AS total
         FROM user_achievements ua
         JOIN achievements a ON ua.achievement_id = a.id
         WHERE ua.wallet_address = $1 OR lower(ua.wallet_address) = lower($1)`,
          [walletAddress]
        )
      : null
  };

  const keys = Object.keys(promises);
  const results = await Promise.all(keys.map((key) => promises[key] || Promise.resolve(null)));

  const counters = {};
  let likesReceivedTotal = 0;
  let viewsReceivedTotal = 0;
  let commentsReceivedTotal = 0;
  let sharesReceivedTotal = 0;
  let savesReceivedTotal = 0;
  for (let i = 0; i < keys.length; i += 1) {
    const key = keys[i];
    const res = results[i];
    if (!res) continue;
    if (key === 'likesReceived') {
      const [artworkLikes, postLikes] = res;
      likesReceivedTotal = (artworkLikes.rows[0]?.total || 0) + (postLikes.rows[0]?.total || 0);
      if (metrics.includes('likesReceived')) counters.likesReceived = likesReceivedTotal;
      continue;
    }
    if (key === 'viewsReceived') {
      const [artworkViews, postViews] = res;
      viewsReceivedTotal = (artworkViews.rows[0]?.total || 0) + (postViews.rows[0]?.total || 0);
      if (metrics.includes('viewsReceived')) counters.viewsReceived = viewsReceivedTotal;
      continue;
    }
    if (key === 'commentsReceived') {
      const [artworkComments, postComments] = res;
      commentsReceivedTotal = (artworkComments.rows[0]?.total || 0) + (postComments.rows[0]?.total || 0);
      continue;
    }
    if (key === 'sharesReceived') {
      const [artworkShares, postShares] = res;
      sharesReceivedTotal = (artworkShares.rows[0]?.total || 0) + (postShares.rows[0]?.total || 0);
      continue;
    }
    if (key === 'savesReceived') {
      savesReceivedTotal = res.rows[0]?.count || 0;
      continue;
    }
    counters[key] = res.rows[0]?.count ?? res.rows[0]?.total ?? 0;
  }

  // Engagement is a derived snapshot based on weighted interactions.
  if (wantsEngagement) {
    counters.engagement =
      likesReceivedTotal * ENGAGEMENT_WEIGHTS.likes +
      commentsReceivedTotal * ENGAGEMENT_WEIGHTS.comments +
      sharesReceivedTotal * ENGAGEMENT_WEIGHTS.shares +
      savesReceivedTotal * ENGAGEMENT_WEIGHTS.saves;
  }

  return counters;
}

async function fetchContentSnapshot({ entityType, entityId, metrics }) {
  if (!UUID_REGEX.test(entityId)) {
    const error = new Error('Invalid entityId');
    error.statusCode = 400;
    throw error;
  }

  const table =
    entityType === ENTITY_TYPES.artwork
      ? 'artworks'
      : entityType === ENTITY_TYPES.collection
        ? 'collections'
        : entityType === ENTITY_TYPES.post
          ? 'community_posts'
          : null;
  if (!table) {
    const error = new Error('Unsupported entity type');
    error.statusCode = 400;
    throw error;
  }

  const selectColumns =
    entityType === ENTITY_TYPES.collection
      ? 'views_count, likes_count, artworks_count'
      : 'views_count, likes_count, comments_count, shares_count';

  const result = await query(
    `SELECT ${selectColumns}
     FROM ${table}
     WHERE id = $1
     LIMIT 1`,
    [entityId]
  );

  const row = result.rows[0];
  if (!row) {
    const error = new Error('Entity not found');
    error.statusCode = 404;
    throw error;
  }

  const counters = {};
  if (metrics.includes('views')) counters.views = row.views_count || 0;
  if (metrics.includes('likes')) counters.likes = row.likes_count || 0;
  if (entityType !== ENTITY_TYPES.collection) {
    if (metrics.includes('comments')) counters.comments = row.comments_count || 0;
    if (metrics.includes('shares')) counters.shares = row.shares_count || 0;

    if (metrics.includes('saves')) {
      const targetType = entityType === ENTITY_TYPES.artwork ? 'artwork' : 'post';
      const saved = await query(
        `SELECT COUNT(*)::int AS count FROM bookmarks WHERE target_type = $1 AND target_id = $2`,
        [targetType, entityId]
      );
      counters.saves = saved.rows[0]?.count || 0;
    }
  }

  if (entityType === ENTITY_TYPES.collection && metrics.includes('artworks')) {
    counters.artworks = row.artworks_count || 0;
  }

  if (metrics.includes('engagement')) {
    counters.engagement =
      entityType === ENTITY_TYPES.collection
        ? (counters.likes || 0) * ENGAGEMENT_WEIGHTS.likes
        : (counters.likes || 0) * ENGAGEMENT_WEIGHTS.likes +
          (counters.comments || 0) * ENGAGEMENT_WEIGHTS.comments +
          (counters.shares || 0) * ENGAGEMENT_WEIGHTS.shares +
          (counters.saves || 0) * ENGAGEMENT_WEIGHTS.saves;
  }

  return counters;
}

async function fetchEventOrExhibitionSnapshot({ entityType, entityId, metrics, scope, req }) {
  if (!UUID_REGEX.test(entityId)) {
    const error = new Error('Invalid entityId');
    error.statusCode = 400;
    throw error;
  }

  const publicOnly = scope !== 'private';
  if (publicOnly) {
    const table = entityType === ENTITY_TYPES.event ? 'events' : 'exhibitions';
    const exists = await query(`SELECT id, status FROM ${table} WHERE id = $1 LIMIT 1`, [entityId]);
    const row = exists.rows[0];
    if (!row) {
      const error = new Error('Entity not found');
      error.statusCode = 404;
      throw error;
    }
    if ((row.status || '').toString().trim().toLowerCase() !== 'published') {
      const error = new Error('Entity not found');
      error.statusCode = 404;
      throw error;
    }
  } else {
    const allowed = await canAccessPrivateStats({ entityType, entityId, req });
    if (!allowed) {
      const error = new Error('Insufficient permissions');
      error.statusCode = req?.user ? 403 : 401;
      throw error;
    }
  }

  const targetType = entityType === ENTITY_TYPES.event ? 'event' : 'exhibition';
  const counters = {};

  let views = 0;
  let shares = 0;

  if (metrics.includes('views') || metrics.includes('engagement')) {
    const result = await query(
      `SELECT COUNT(*)::int AS count
       FROM analytics_events
       WHERE event_type = 'view'
         AND target_type = $1
         AND target_id = $2`,
      [targetType, entityId]
    );
    views = result.rows[0]?.count || 0;
    if (metrics.includes('views')) counters.views = views;
  }

  if (metrics.includes('shares') || metrics.includes('engagement')) {
    const result = await query(
      `SELECT COUNT(*)::int AS count
       FROM analytics_events
       WHERE event_type = 'share'
         AND target_type = $1
         AND target_id = $2`,
      [targetType, entityId]
    );
    shares = result.rows[0]?.count || 0;
    if (metrics.includes('shares')) counters.shares = shares;
  }

  if (entityType === ENTITY_TYPES.exhibition && metrics.includes('artworks')) {
    const result = await query(
      `SELECT COUNT(*)::int AS count
       FROM exhibition_artworks
       WHERE exhibition_id = $1`,
      [entityId]
    );
    counters.artworks = result.rows[0]?.count || 0;
  }

  if (metrics.includes('engagement')) {
    counters.engagement = views + shares * ENGAGEMENT_WEIGHTS.shares;
  }

  return counters;
}

async function fetchPlatformSnapshot({ metrics }) {
  const result = await query(
    `SELECT
        (SELECT COUNT(*)::int FROM users) AS users,
        (SELECT COUNT(*)::int FROM profiles) AS profiles,
        (SELECT COUNT(*)::int FROM artworks WHERE is_active = true AND is_public = true) AS artworks,
        (SELECT COUNT(*)::int FROM artworks WHERE is_active = true AND is_public = true AND is_ar_enabled = true) AS ar_enabled_artworks,
        (SELECT COUNT(*)::int FROM collections) AS collections,
        (SELECT COUNT(*)::int FROM community_posts WHERE is_active = true AND is_public = true) AS posts,
        (SELECT COUNT(*)::int FROM groups WHERE is_public = true) AS groups,
        (SELECT COUNT(*)::int FROM likes) AS likes,
        (SELECT COUNT(*)::int FROM follows) AS follows,
        (SELECT COUNT(*)::int FROM analytics_events WHERE event_type = 'view') AS views`,
    []
  );

  const row = result.rows[0] || {};
  const counters = {};
  if (metrics.includes('users')) counters.users = row.users || 0;
  if (metrics.includes('profiles')) counters.profiles = row.profiles || 0;
  if (metrics.includes('artworks')) counters.artworks = row.artworks || 0;
  if (metrics.includes('arEnabledArtworks')) counters.arEnabledArtworks = row.ar_enabled_artworks || 0;
  if (metrics.includes('collections')) counters.collections = row.collections || 0;
  if (metrics.includes('posts')) counters.posts = row.posts || 0;
  if (metrics.includes('groups')) counters.groups = row.groups || 0;
  if (metrics.includes('likes')) counters.likes = row.likes || 0;
  if (metrics.includes('follows')) counters.follows = row.follows || 0;
  if (metrics.includes('views')) counters.views = row.views || 0;
  return counters;
}

async function fetchDaoSnapshot({ metrics }) {
  const result = await query(
    `SELECT
        (SELECT COUNT(*)::int FROM dao_proposals) AS dao_total_proposals,
        (SELECT COUNT(*)::int FROM dao_proposals WHERE status IN ('active', 'voting')) AS dao_active_proposals,
        (SELECT COUNT(*)::int FROM dao_votes) AS dao_votes_cast,
        (SELECT COUNT(*)::int FROM dao_delegates) AS dao_delegates,
        (SELECT COALESCE(AVG(voting_power), 0)::numeric FROM dao_delegates) AS dao_average_voting_power,
        (
          SELECT COALESCE(SUM(amount), 0)::numeric
          FROM dao_transactions
          WHERE tx_type = 'treasury'
            AND status <> 'failed'
        ) AS dao_treasury_amount,
        (
          SELECT COALESCE(SUM(amount), 0)::numeric
          FROM dao_transactions
          WHERE amount > 0
            AND status <> 'failed'
        ) AS dao_treasury_inflow,
        (
          SELECT COALESCE(SUM(ABS(amount)), 0)::numeric
          FROM dao_transactions
          WHERE amount < 0
            AND status <> 'failed'
        ) AS dao_treasury_outflow,
        (
          SELECT COUNT(*)::int
          FROM (
            SELECT id
            FROM dao_transactions
            WHERE status <> 'failed'
            ORDER BY occurred_at DESC
            LIMIT 5
          ) recent_transactions
        ) AS dao_recent_transactions`,
    []
  );

  const row = result.rows[0] || {};
  const counters = {};
  if (metrics.includes('daoTotalProposals')) counters.daoTotalProposals = Number(row.dao_total_proposals || 0);
  if (metrics.includes('daoActiveProposals')) counters.daoActiveProposals = Number(row.dao_active_proposals || 0);
  if (metrics.includes('daoVotesCast')) counters.daoVotesCast = Number(row.dao_votes_cast || 0);
  if (metrics.includes('daoDelegates')) counters.daoDelegates = Number(row.dao_delegates || 0);
  if (metrics.includes('daoAverageVotingPower')) {
    counters.daoAverageVotingPower = Math.round(Number(row.dao_average_voting_power || 0));
  }
  if (metrics.includes('daoTreasuryAmount')) counters.daoTreasuryAmount = Math.round(Number(row.dao_treasury_amount || 0));
  if (metrics.includes('daoTreasuryInflow')) counters.daoTreasuryInflow = Math.round(Number(row.dao_treasury_inflow || 0));
  if (metrics.includes('daoTreasuryOutflow')) counters.daoTreasuryOutflow = Math.round(Number(row.dao_treasury_outflow || 0));
  if (metrics.includes('daoRecentTransactions')) {
    counters.daoRecentTransactions = Number(row.dao_recent_transactions || 0);
  }
  return counters;
}

async function getSnapshot({ entityType, entityId, metrics: rawMetrics, scope: rawScope, groupBy, req }) {
  const normalizedType = normalizeEntityType(entityType);
  if (!normalizedType) {
    const error = new Error('Invalid entityType');
    error.statusCode = 400;
    throw error;
  }

  const normalizedScope = normalizeScope(rawScope);
  const normalizedEntityId = normalizeEntityIdForType(normalizedType, entityId);

  const cacheProperty = (() => {
    const raw = req?.query?.property ?? req?.body?.property ?? req?.query?.site ?? req?.body?.site;
    const value = raw !== undefined && raw !== null ? String(raw).trim() : '';
    return value || null;
  })();

  if (!normalizedEntityId) {
    const error = new Error('Missing entityId');
    error.statusCode = 400;
    throw error;
  }

  const normalizedGroupBy = normalizeSnapshotGroupBy(groupBy);

  if (normalizedScope === 'private') {
    const allowed = await canAccessPrivateStats({
      entityType: normalizedType,
      entityId: normalizedEntityId,
      req
    });
    if (!allowed) {
      const error = new Error('Insufficient permissions');
      error.statusCode = req?.user ? 403 : 401;
      throw error;
    }
  }

  const metrics = normalizeMetricList(normalizedType, rawMetrics, normalizedScope);
  const cacheKey = buildStatsSnapshotKey(normalizedType, normalizedEntityId, {
    scope: normalizedScope,
    metrics,
    groupBy: normalizedGroupBy,
    property: cacheProperty
  });

  return cache.wrap(
    cacheKey,
    async () => {
      if (normalizedType === ENTITY_TYPES.user) {
        const ctx = await resolveUserContext(normalizedEntityId);
        if (!ctx.walletAddress) {
          const error = new Error('User not found');
          error.statusCode = 404;
          throw error;
        }
        const counters = await fetchUserSnapshot({
          walletAddress: ctx.walletAddress,
          userId: ctx.userId,
          metrics,
          scope: normalizedScope
        });
        return {
          entityType: normalizedType,
          entityId: ctx.walletAddress,
          scope: normalizedScope,
          metrics,
          counters,
          generatedAt: new Date().toISOString()
        };
      }

      if (normalizedType === ENTITY_TYPES.platform) {
        const counters = await fetchPlatformSnapshot({ metrics });
        return {
          entityType: normalizedType,
          entityId: 'global',
          scope: 'public',
          metrics,
          counters,
          generatedAt: new Date().toISOString()
        };
      }

      if (normalizedType === ENTITY_TYPES.dao) {
        const counters = await fetchDaoSnapshot({ metrics });
        return {
          entityType: normalizedType,
          entityId: 'governance',
          scope: normalizedScope,
          metrics,
          counters,
          generatedAt: new Date().toISOString()
        };
      }

      if (normalizedType === ENTITY_TYPES.event || normalizedType === ENTITY_TYPES.exhibition) {
        const counters = await fetchEventOrExhibitionSnapshot({
          entityType: normalizedType,
          entityId: normalizedEntityId,
          metrics,
          scope: normalizedScope,
          req
        });
        return {
          entityType: normalizedType,
          entityId: normalizedEntityId,
          scope: normalizedScope,
          metrics,
          counters,
          generatedAt: new Date().toISOString()
        };
      }

      const counters = await fetchContentSnapshot({
        entityType: normalizedType,
        entityId: normalizedEntityId,
        metrics
      });
      return {
        entityType: normalizedType,
        entityId: normalizedEntityId,
        scope: normalizedScope,
        metrics,
        counters,
        generatedAt: new Date().toISOString()
      };
    },
    { ttlSeconds: STATS_SNAPSHOT_TTL }
  );
}

function buildSeriesResult({ entityType, entityId, scope, metric, bucket, from, to, groupBy, series }) {
  return {
    entityType,
    entityId,
    scope,
    metric,
    bucket,
    from: from.toISOString(),
    to: to.toISOString(),
    groupBy: groupBy || null,
    series,
    generatedAt: new Date().toISOString()
  };
}

async function fetchSeriesFromSql({ sql, params, groupBy }) {
  const result = await query(sql, params);
  return result.rows.map((row) => ({
    t: row.bucket instanceof Date ? row.bucket.toISOString() : new Date(row.bucket).toISOString(),
    v: Math.round(Number(row.value || 0)),
    ...(groupBy ? { g: row.group_key || 'unknown' } : {})
  }));
}

function sumSeries(a, b) {
  const map = new Map();
  for (const point of a || []) {
    map.set(point.t, (map.get(point.t) || 0) + (point.v || 0));
  }
  for (const point of b || []) {
    map.set(point.t, (map.get(point.t) || 0) + (point.v || 0));
  }
  return [...map.entries()].map(([t, v]) => ({ t, v })).sort((x, y) => x.t.localeCompare(y.t));
}

function scaleSeries(series, factor) {
  const mult = Number(factor);
  if (!Number.isFinite(mult) || mult === 1) {
    return (series || []).map((p) => ({ t: p.t, v: p.v || 0 }));
  }
  return (series || []).map((p) => ({ t: p.t, v: (p.v || 0) * mult }));
}

function weightedSumSeries(parts) {
  let out = [];
  for (const part of parts || []) {
    if (!part || !Array.isArray(part.series)) continue;
    const weight = Number(part.weight);
    out = sumSeries(out, scaleSeries(part.series, Number.isFinite(weight) ? weight : 1));
  }
  return out;
}

async function fetchContentSeries({ entityType, entityId, metric, window, groupBy, scope }) {
  const bucket = window.bucket;
  const from = window.from;
  const to = window.to;
  const isPublicScope = scope !== 'private';

  if (!UUID_REGEX.test(entityId)) {
    const error = new Error('Invalid entityId');
    error.statusCode = 400;
    throw error;
  }

  if (entityType === ENTITY_TYPES.collection) {
    const error = new Error('Series not supported for collections');
    error.statusCode = 400;
    throw error;
  }

  const targetType = entityType === ENTITY_TYPES.artwork ? 'artwork' : 'post';
  const column = entityType === ENTITY_TYPES.artwork ? 'artwork_id' : 'post_id';

  if (metric === 'views') {
    const groupExpr = groupBy === 'source' ? `COALESCE((metadata->>'source'), 'unknown')` : null;
    const sql = `
      SELECT
        date_trunc('${bucket}', created_at) AS bucket,
        ${groupExpr ? `${groupExpr} AS group_key,` : ''}
        COUNT(*)::int AS value
      FROM analytics_events
      WHERE event_type = 'view'
        AND target_type = $1
        AND target_id = $2
        AND created_at >= $3
        AND created_at < $4
      GROUP BY bucket ${groupExpr ? ', group_key' : ''}
      ORDER BY bucket ASC ${groupExpr ? ', group_key ASC' : ''}
    `;
    const series = await fetchSeriesFromSql({
      sql,
      params: [targetType, entityId, from.toISOString(), to.toISOString()],
      groupBy: groupExpr ? 'source' : null
    });
    return buildSeriesResult({
      entityType,
      entityId,
      scope,
      metric,
      bucket,
      from,
      to,
      groupBy: groupExpr ? 'source' : null,
      series
    });
  }

  if (metric === 'likes') {
    const sql = `
      SELECT
        date_trunc('${bucket}', created_at) AS bucket,
        COUNT(*)::int AS value
      FROM likes
      WHERE target_type = $1
        AND target_id = $2
        AND created_at >= $3
        AND created_at < $4
      GROUP BY bucket
      ORDER BY bucket ASC
    `;
    const series = await fetchSeriesFromSql({
      sql,
      params: [targetType, entityId, from.toISOString(), to.toISOString()],
      groupBy: null
    });
    return buildSeriesResult({
      entityType,
      entityId,
      scope,
      metric,
      bucket,
      from,
      to,
      groupBy: null,
      series
    });
  }

  if (metric === 'comments') {
    const sql = `
      SELECT
        date_trunc('${bucket}', created_at) AS bucket,
        COUNT(*)::int AS value
      FROM comments
      WHERE ${column} = $1
        AND created_at >= $2
        AND created_at < $3
      GROUP BY bucket
      ORDER BY bucket ASC
    `;
    const series = await fetchSeriesFromSql({
      sql,
      params: [entityId, from.toISOString(), to.toISOString()],
      groupBy: null
    });
    return buildSeriesResult({
      entityType,
      entityId,
      scope,
      metric,
      bucket,
      from,
      to,
      groupBy: null,
      series
    });
  }

  if (metric === 'shares') {
    const groupExpr = groupBy === 'source' ? `COALESCE((metadata->>'source'), 'unknown')` : null;
    const sql = `
      SELECT
        date_trunc('${bucket}', created_at) AS bucket,
        ${groupExpr ? `${groupExpr} AS group_key,` : ''}
        COUNT(*)::int AS value
      FROM analytics_events
      WHERE event_type = 'share'
        AND target_type = $1
        AND target_id = $2
        AND created_at >= $3
        AND created_at < $4
      GROUP BY bucket ${groupExpr ? ', group_key' : ''}
      ORDER BY bucket ASC ${groupExpr ? ', group_key ASC' : ''}
    `;
    const series = await fetchSeriesFromSql({
      sql,
      params: [targetType, entityId, from.toISOString(), to.toISOString()],
      groupBy: groupExpr ? 'source' : null
    });
    return buildSeriesResult({
      entityType,
      entityId,
      scope,
      metric,
      bucket,
      from,
      to,
      groupBy: groupExpr ? 'source' : null,
      series
    });
  }

  if (metric === 'saves') {
    const sql = `
      SELECT
        date_trunc('${bucket}', created_at) AS bucket,
        COUNT(*)::int AS value
      FROM bookmarks
      WHERE target_type = $1
        AND target_id = $2
        AND created_at >= $3
        AND created_at < $4
      GROUP BY bucket
      ORDER BY bucket ASC
    `;
    const series = await fetchSeriesFromSql({
      sql,
      params: [targetType, entityId, from.toISOString(), to.toISOString()],
      groupBy: null
    });
    return buildSeriesResult({
      entityType,
      entityId,
      scope,
      metric,
      bucket,
      from,
      to,
      groupBy: null,
      series
    });
  }

  if (metric === 'engagement') {
    const [likes, comments, shares, saves] = await Promise.all([
      fetchContentSeries({
        entityType,
        entityId,
        metric: 'likes',
        window,
        groupBy: null,
        scope
      }),
      fetchContentSeries({
        entityType,
        entityId,
        metric: 'comments',
        window,
        groupBy: null,
        scope
      }),
      fetchContentSeries({
        entityType,
        entityId,
        metric: 'shares',
        window,
        groupBy: null,
        scope
      }),
      fetchContentSeries({
        entityType,
        entityId,
        metric: 'saves',
        window,
        groupBy: null,
        scope
      })
    ]);
    const series = weightedSumSeries([
      { series: likes.series, weight: ENGAGEMENT_WEIGHTS.likes },
      { series: comments.series, weight: ENGAGEMENT_WEIGHTS.comments },
      { series: shares.series, weight: ENGAGEMENT_WEIGHTS.shares },
      { series: saves.series, weight: ENGAGEMENT_WEIGHTS.saves }
    ]);
    return buildSeriesResult({
      entityType,
      entityId,
      scope,
      metric,
      bucket,
      from,
      to,
      groupBy: null,
      series
    });
  }

  const error = new Error('Unsupported metric');
  error.statusCode = 400;
  throw error;
}

async function fetchEventOrExhibitionSeries({ entityType, entityId, metric, window, groupBy, scope, req }) {
  const bucket = window.bucket;
  const from = window.from;
  const to = window.to;

  if (!UUID_REGEX.test(entityId)) {
    const error = new Error('Invalid entityId');
    error.statusCode = 400;
    throw error;
  }

  const publicOnly = scope !== 'private';
  if (publicOnly) {
    const table = entityType === ENTITY_TYPES.event ? 'events' : 'exhibitions';
    const exists = await query(`SELECT id, status FROM ${table} WHERE id = $1 LIMIT 1`, [entityId]);
    const row = exists.rows[0];
    if (!row) {
      const error = new Error('Entity not found');
      error.statusCode = 404;
      throw error;
    }
    if ((row.status || '').toString().trim().toLowerCase() !== 'published') {
      const error = new Error('Entity not found');
      error.statusCode = 404;
      throw error;
    }
  } else {
    const allowed = await canAccessPrivateStats({ entityType, entityId, req });
    if (!allowed) {
      const error = new Error('Insufficient permissions');
      error.statusCode = req?.user ? 403 : 401;
      throw error;
    }
  }

  const targetType = entityType === ENTITY_TYPES.event ? 'event' : 'exhibition';

  if (metric === 'views' || metric === 'shares') {
    const eventType = metric === 'views' ? 'view' : 'share';
    const groupExpr = groupBy === 'source' ? `COALESCE((metadata->>'source'), 'unknown')` : null;
    const sql = `
      SELECT
        date_trunc('${bucket}', created_at) AS bucket,
        ${groupExpr ? `${groupExpr} AS group_key,` : ''}
        COUNT(*)::int AS value
      FROM analytics_events
      WHERE event_type = $1
        AND target_type = $2
        AND target_id = $3
        AND created_at >= $4
        AND created_at < $5
      GROUP BY bucket ${groupExpr ? ', group_key' : ''}
      ORDER BY bucket ASC ${groupExpr ? ', group_key ASC' : ''}
    `;
    const series = await fetchSeriesFromSql({
      sql,
      params: [eventType, targetType, entityId, from.toISOString(), to.toISOString()],
      groupBy: groupExpr ? 'source' : null
    });
    return buildSeriesResult({
      entityType,
      entityId,
      scope,
      metric,
      bucket,
      from,
      to,
      groupBy: groupExpr ? 'source' : null,
      series
    });
  }

  if (metric === 'engagement') {
    const [views, shares] = await Promise.all([
      fetchEventOrExhibitionSeries({
        entityType,
        entityId,
        metric: 'views',
        window,
        groupBy: null,
        scope,
        req
      }),
      fetchEventOrExhibitionSeries({
        entityType,
        entityId,
        metric: 'shares',
        window,
        groupBy: null,
        scope,
        req
      })
    ]);
    const series = weightedSumSeries([
      { series: views.series, weight: 1 },
      { series: shares.series, weight: ENGAGEMENT_WEIGHTS.shares }
    ]);
    return buildSeriesResult({
      entityType,
      entityId,
      scope,
      metric,
      bucket,
      from,
      to,
      groupBy: null,
      series
    });
  }

  const error = new Error('Unsupported metric');
  error.statusCode = 400;
  throw error;
}

